/**
 * server.js - local player so the solved stream works in any browser.
 *
 *   node server.js        -> http://127.0.0.1:8766
 *
 * Routes:
 *   GET /          play.html (generated by build-play.js)
 *   GET /api/link  solved cipher info as JSON
 *   GET /stream    Range-aware proxy of the solved googlevideo URL
 *
 * The proxy is the primary path: browsers often refuse or silently stall a bare
 * googlevideo URL inside <video>, so play.html points at /stream and keeps the
 * direct URL only as a fallback. cipher.txt is read on every request, so
 * dropping in a fresh cipher works without restarting.
 */
'use strict';

const http = require('http');
const fs = require('fs');
const path = require('path');
const { Readable } = require('stream');
const { solveDetailed, cleanCipher } = require('./solver.js');
const { solveSmart } = require('./vm-solve.js');
const { ensurePlayer, refreshIfChanged } = require('./engine/fetch-player.js');

const PORT = Number(process.env.PORT || 8766);
const HOST = process.env.HOST || '127.0.0.1';
const CIPHER = process.env.CIPHER || path.join(__dirname, 'cipher.txt');
const BASE_FILE = process.env.BASE || path.join(__dirname, 'base.js');
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36';
const IDLE_MS = Number(process.env.IDLE_MS || 45000);
const AUTO_OPEN = process.env.OPEN === '1';

let lastActivity = Date.now();
let stopping = false;
let sseClients = 0;
let closeTimer = null;

function stopServer(reason) {
  if (stopping) return;
  stopping = true;
  if (closeTimer) { clearTimeout(closeTimer); closeTimer = null; }
  console.log(`\nplayer : stopping (${reason})`);
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 1500).unref();
}

// One solve per cipher text. `/api/link` and `/stream` are called repeatedly
// (the video element issues Range requests), and re-solving each time would
// burn the player's rate limit and could start returning 403 mid-playback.
let solvedCache = { key: null, at: 0, value: null };
const SOLVE_TTL_MS = Number(process.env.SOLVE_TTL_MS || 10 * 60 * 1000);

// The player bundle is the one file this app needs. Fetch it on first use so a
// fresh clone works without hunting through DevTools. The promise is shared so
// concurrent requests cannot start several downloads.
let baseReady = null;
function ensureBase(force) {
  if (!baseReady || force) {
    baseReady = ensurePlayer(BASE_FILE, { force: !!force })
      .then((r) => {
        if (r.fetched) console.log(`player : downloaded base.js (${(r.bytes / 1048576).toFixed(2)} MB, build ${r.id})`);
        else if (r.warning) console.log(`player : kept existing base.js (${r.warning})`);
        return r;
      })
      .catch((e) => { baseReady = null; throw e; });
  }
  return baseReady;
}

async function solveLocal() {
  if (!fs.existsSync(CIPHER)) return { error: `missing ${CIPHER}` };
  let cipher;
  try { cipher = cleanCipher(fs.readFileSync(CIPHER, 'utf8')); } catch (e) { return { error: e.message }; }
  if (!cipher) return { error: `no signatureCipher in ${CIPHER}` };

  const fresh = solvedCache.value && solvedCache.key === cipher
    && Date.now() - solvedCache.at < SOLVE_TTL_MS;
  if (fresh) return solvedCache.value;

  const q = new URLSearchParams(cipher);
  const rawS = decodeURIComponent(q.get('s') || '');
  const rawUrl = q.get('url') || '';
  if (rawS.length < 10 || !/^https?:\/\/[^/]+\//.test(rawUrl)) {
    return { error: `no usable signatureCipher in ${path.basename(CIPHER)} - paste it on one line` };
  }

  try {
    await ensureBase();
    const base = new URL(rawUrl);
    // The engine is async: reading a player and probing googlevideo cannot be
    // done synchronously. Awaiting here is what keeps /api/link and /stream
    // returning a real url instead of `undefined`.
    let solved = await solveDetailed(cipher, { base: BASE_FILE });
    if (!solved || !solved.url) {
      // Ask YouTube whether it shipped a new build. Only then replace the file
      // and retry - a 403 from an expired cipher must not trigger a download.
      const r = await refreshIfChanged(BASE_FILE).catch(() => null);
      if (r && r.fetched) {
        console.log(`player : new build ${r.id} downloaded, retrying`);
        solved = await solveDetailed(cipher, { base: BASE_FILE, force: true });
      }
    }
    if (!solved || !solved.url) {
      const why = solved && solved.report && solved.report.error;
      return { error: why || 'no playable url', engine: solved && solved.engine };
    }
    const value = {
      url: solved.url,
      stream: `http://${HOST}:${PORT}/stream`,
      engine: solved.engine,
      itag: base.searchParams.get('itag'),
      rawS: solved.rawS,
      solvedSig: solved.sig,
      rawN: solved.rawN,
      solvedN: solved.n,
    };
    solvedCache = { key: cipher, at: Date.now(), value };
    return value;
  } catch (e) { return { error: e.message }; }
}

function sendJson(res, status, obj) {
  const b = Buffer.from(JSON.stringify(obj, null, 2));
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': b.length, 'cache-control': 'no-store' });
  res.end(b);
}

function sendFile(res, file) {
  if (!fs.existsSync(file)) { sendJson(res, 404, { error: 'not found', file }); return; }
  const b = fs.readFileSync(file);
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'content-length': b.length, 'cache-control': 'no-store' });
  res.end(b);
}

async function proxyStream(req, res) {
  try {
    const solved = await solveLocal();
    if (solved.error) throw new Error(solved.error);
    const headers = { 'user-agent': UA };
    if (req.headers.range) headers.range = req.headers.range;
    const upstream = await fetch(solved.url, { headers });
    const out = {
      'content-type': upstream.headers.get('content-type') || 'video/mp4',
      'accept-ranges': 'bytes',
      'cache-control': 'no-store',
    };
    for (const h of ['content-length', 'content-range']) {
      const v = upstream.headers.get(h);
      if (v) out[h] = v;
    }
    res.writeHead(upstream.status, out);
    if (!upstream.body) { res.end(); return; }
    Readable.fromWeb(upstream.body).pipe(res);
  } catch (e) {
    sendJson(res, 502, { error: e.message });
  }
}

// ---------------------------------------------------------------------------
// live solve: stream every stage to the browser as Server-Sent Events
// ---------------------------------------------------------------------------

function sseHead(res) {
  res.writeHead(200, {
    'content-type': 'text/event-stream',
    'cache-control': 'no-store',
    connection: 'keep-alive',
    'x-accel-buffering': 'no',
  });
}

function sseSend(res, obj) {
  try { res.write('data: ' + JSON.stringify(obj) + '\n\n'); } catch (e) { /* client gone */ }
}

async function solveStream(req, res) {
  sseHead(res);
  sseClients += 1;
  if (closeTimer) { clearTimeout(closeTimer); closeTimer = null; }

  const started = Date.now();
  let closed = false;
  req.on('close', () => {
    closed = true;
    sseClients = Math.max(0, sseClients - 1);
  });

  const send = (o) => { if (!closed) sseSend(res, { ...o, t: Date.now() - started }); };
  const step = (stage, message) => send({ type: 'stage', stage, message });

  try {
    if (!fs.existsSync(CIPHER)) throw new Error('missing ' + CIPHER);
    const raw = fs.readFileSync(CIPHER, 'utf8');

    step('read', 'reading cipher.txt');
    const cipher = cleanCipher(raw);
    const q = new URLSearchParams(cipher);
    const rawS = decodeURIComponent(q.get('s') || '');
    const rawUrl = q.get('url') || '';
    if (rawS.length < 10 || !/^https?:\/\/[^/]+\//.test(rawUrl)) {
      throw new Error(`no usable signatureCipher in ${path.basename(CIPHER)} - paste it on one line`);
    }
    const base = new URL(rawUrl);
    const rawN = base.searchParams.get('n');
    send({
      type: 'cipher',
      itag: base.searchParams.get('itag'),
      sLen: rawS.length,
      n: rawN,
      expire: Number(base.searchParams.get('expire')) || null,
      host: base.host,
    });
    if (!rawS) throw new Error('cipher has no s - paste the signatureCipher value');

    step('load', 'loading ' + path.basename(BASE_FILE));
    await ensureBase();
    send({ type: 'build', file: path.basename(BASE_FILE), bytes: fs.statSync(BASE_FILE).size });

    // Drive the real engine, forwarding each event. The names here must match
    // exactly what live.html listens for (`probe` starts a row, `probe-result`
    // finishes it) or the rows stay stuck on "testing".
    let probeT0 = 0;
    const onEvent = (ev) => {
      if (ev.stage === 'plan') {
        step('plan', 'building candidate list');
        send({ type: 'plan', candidates: ev.candidates, nCandidates: ev.nCandidates });
      } else if (ev.stage === 'probe') {
        probeT0 = Date.now();
        send({ type: 'probe', probes: ev.probes, label: ev.label, tier: ev.tier, n: ev.n });
      } else if (ev.stage === 'probe-result') {
        send({
          type: 'probe-result', probes: ev.probes, label: ev.label, tier: ev.tier,
          status: ev.status, ok: ev.ok, t: Date.now() - probeT0,
        });
      }
    };

    let solved = await solveSmart(cipher, {
      base: BASE_FILE,
      force: u_searchForce(req),
      onEvent,
    });

    // Every candidate 403. Check whether YouTube replaced the player; only a
    // genuinely new build is worth another full search.
    if (!solved || !solved.url) {
      const r = await refreshIfChanged(BASE_FILE).catch(() => null);
      if (r && r.fetched) {
        step('refresh', 'new player build ' + r.id + ' downloaded - retrying');
        send({ type: 'build', file: path.basename(BASE_FILE), bytes: fs.statSync(BASE_FILE).size });
        solved = await solveSmart(cipher, { base: BASE_FILE, force: true, onEvent });
      } else if (r && r.unchanged) {
        step('refresh', 'player build is current - the cipher is the problem');
      }
    }

    // A failed solve is a result, not an exception: say plainly that every
    // candidate was rejected so the page can stop spinning and explain why.
    if (!solved || solved.ok === false || !solved.url) {
      const eng = (solved && solved.engine) || {};
      send({
        type: 'failed',
        probes: eng.probes || 0,
        reason: eng.error || 'no working candidate found for this player build',
        itag: base.searchParams.get('itag'),
        ms: Date.now() - started,
      });
      send({ type: 'done', ms: Date.now() - started });
      try { res.end(); } catch (e) {}
      return;
    }

    send({
      type: 'solved',
      url: solved.url,
      sig: solved.sig,
      n: solved.solvedN,
      rawN: solved.rawN,
      source: (solved.engine && solved.engine.source) || 'solved',
      probes: (solved.engine && solved.engine.probes) || 0,
      itag: base.searchParams.get('itag'),
      ms: Date.now() - started,
    });
    send({ type: 'done', ms: Date.now() - started });
  } catch (e) {
    send({ type: 'error', message: e.message });
    send({ type: 'done', ms: Date.now() - started });
  }
  try { res.end(); } catch (e) { /* already closed */ }
}

function u_searchForce(req) {
  try { return new URL(req.url, 'http://x').searchParams.get('force') === '1'; } catch (e) { return false; }
}

const server = http.createServer(async (req, res) => {
  lastActivity = Date.now();
  const u = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  try {
    if (u.pathname === '/' || u.pathname === '/play.html') {
      const page = path.join(__dirname, 'play.html');
      // No built page yet (fresh clone, or the build failed). /live always
      // exists, so send the user there instead of a bare 404.
      if (!fs.existsSync(page)) { res.writeHead(302, { location: '/live' }); return res.end(); }
      return sendFile(res, page);
    }
    if (u.pathname === '/api/link') return sendJson(res, 200, await solveLocal());
    if (u.pathname === '/api/experience') {
      const store = require('./engine/store.js');
      return sendJson(res, 200, store.experienceSummary());
    }
    if (u.pathname === '/stream') return void (await proxyStream(req, res));
    if (u.pathname === '/health') return sendJson(res, 200, { ok: true, uptime: process.uptime() });
    if (u.pathname === '/ping') { res.writeHead(204, { 'cache-control': 'no-store' }); return res.end(); }
    if (u.pathname === '/bye') { res.writeHead(204, { 'cache-control': 'no-store' }); res.end(); setTimeout(() => stopServer('page closed'), 150); return; }
    if (u.pathname === '/api/solve') return void (await solveStream(req, res));
    if (u.pathname === '/live' || u.pathname === '/live.html') return sendFile(res, path.join(__dirname, 'live.html'));
    if (u.pathname === '/play') return sendFile(res, path.join(__dirname, 'play.html'));
    sendJson(res, 404, { error: 'not found' });
  } catch (e) {
    sendJson(res, 500, { error: e.message });
  }
});

server.listen(PORT, HOST, () => {
  console.log(`player : http://${HOST}:${PORT}/`);
  console.log(`link   : http://${HOST}:${PORT}/api/link`);
  console.log(`stream : http://${HOST}:${PORT}/stream`);
  console.log(`life   : auto-stops ${IDLE_MS / 1000}s after the page closes`);

  if (AUTO_OPEN) {
    const { spawn } = require('child_process');
    spawn('cmd', ['/c', 'start', '""', `http://${HOST}:${PORT}/live`], {
      detached: true, stdio: 'ignore', windowsHide: true,
    }).unref();
  }
});

// Stop on its own: a closed page sends /bye; if that is missed, go idle.
setInterval(() => {
  if (!stopping && Date.now() - lastActivity > IDLE_MS) stopServer('idle');
}, 5000).unref();
